from fractions import Fraction as F
from itertools import combinations

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_seg(p, s):
    a, b = s
    return cross(a, b, p) == 0 and min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def intersect(s, t):
    (x1, y1), (x2, y2) = s
    (x3, y3), (x4, y4) = t
    d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if d == 0:
        return None
    u = F((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4), d)
    p = (x1 + u * (x2 - x1), y1 + u * (y2 - y1))
    return p if on_seg(p, s) and on_seg(p, t) else None

def count_triangles(segs):
    segs = [tuple((F(x), F(y)) for x, y in s) for s in segs]
    pts = {p for s in segs for p in s}
    for s, t in combinations(segs, 2):
        p = intersect(s, t)
        if p is not None:
            pts.add(p)
    joined = lambda p, q: any(on_seg(p, s) and on_seg(q, s) for s in segs)
    return sum(1 for a, b, c in combinations(sorted(pts), 3)
               if cross(a, b, c) != 0 and joined(a, b) and joined(b, c) and joined(a, c))

