from itertools import combinations

def covered(a, b, segs, horizontal, at):
    """Is the straight piece from a to b (on line y=at if horizontal else x=at) fully drawn?"""
    spans = sorted((min(s[0][0], s[1][0]), max(s[0][0], s[1][0])) if horizontal else
                   (min(s[0][1], s[1][1]), max(s[0][1], s[1][1]))
                   for s in segs
                   if (horizontal and s[0][1] == s[1][1] == at) or (not horizontal and s[0][0] == s[1][0] == at))
    reach = a
    for lo, hi in spans:
        if lo <= reach < hi:
            reach = hi
        if reach >= b:
            return True
    return reach >= b

def count_squares(segs):
    xs = sorted({p[0] for s in segs for p in s})
    ys = sorted({p[1] for s in segs for p in s})
    by_size = {}
    for x1, x2 in combinations(xs, 2):
        k = x2 - x1
        for y1 in ys:
            y2 = y1 + k
            if (covered(x1, x2, segs, True, y1) and covered(x1, x2, segs, True, y2)
                    and covered(y1, y2, segs, False, x1) and covered(y1, y2, segs, False, x2)):
                by_size[k] = by_size.get(k, 0) + 1
    return by_size

def box(x1, y1, x2, y2):
    return [((x1, y1), (x2, y1)), ((x2, y1), (x2, y2)), ((x2, y2), (x1, y2)), ((x1, y2), (x1, y1))]

