from fractions import Fraction as F
from itertools import combinations

def semicircles(arcs):
    """arcs: drawn semicircles given by the two ends of their diameter. List each once by its end points."""
    found = {tuple(sorted(a)) for a in arcs}
    groups = {}
    for a, b in found:
        r = abs(F(b[0]) - F(a[0])) / 2
        groups.setdefault(r, []).append((a, b))
    return found, groups

