# straight lines: merge collinear overlapping pieces, then count each line once by its end points
def lines(segs):
    def key(s):
        (x1, y1), (x2, y2) = s
        a, b = y2 - y1, x1 - x2
        c = a * x1 + b * y1
        from math import gcd
        g = gcd(gcd(a, b), c) or 1
        if a < 0 or (a == 0 and b < 0):
            g = -g
        return (a // g, b // g, c // g)
    by_line = {}
    for s in segs:
        p, q = sorted(s)
        by_line.setdefault(key(s), []).append((p, q))
    total = 0
    for pieces in by_line.values():
        pieces.sort()
        end = None
        for p, q in pieces:
            if end is None or p > end:
                total += 1
                end = q
            else:
                end = max(end, q)
    return total

